// action
import * as actions from '../action/auth.action';
import { AuthStateRecord } from './auth.state'; // Model

import { LoginResponseModel } from '../models/login.response.model';
export const initialState = new AuthStateRecord();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    case actions.ActionTypes.DO_LOGIN:
      {
        return Object.assign({}, state, {
          loginSuccess: {},
          loginRequestLoading: true,
          loginRequestLoaded: false,
          loginRequestFailed: false
        });
      }

    case actions.ActionTypes.DO_LOGIN_SUCCESS:
      {
        return Object.assign({}, state, {
          loginSuccess: new LoginResponseModel(payload),
          loginRequestLoading: false,
          loginRequestLoaded: true,
          loginRequestFailed: false
        });
      }

    case actions.ActionTypes.DO_LOGIN_FAIL:
      {
        return Object.assign({}, state, {
          loginSuccess: {},
          loginRequestLoading: false,
          loginRequestLoaded: true,
          loginRequestFailed: true
        });
      }

    case actions.ActionTypes.DO_FORGOT_PASSWORD:
      {
        return Object.assign({}, state, {
          forgotPasswordResponse: false,
          forgotPasswordRequestLoading: true,
          forgotPasswordRequestLoaded: false,
          forgotPasswordRequestFailed: false
        });
      }

    case actions.ActionTypes.DO_FORGOT_PASSWORD_SUCCESS:
      {
        return Object.assign({}, state, {
          forgotPasswordResponse: true,
          forgotPasswordRequestLoading: false,
          forgotPasswordRequestLoaded: true,
          forgotPasswordRequestFailed: false
        });
      }

    case actions.ActionTypes.DO_FORGOT_PASSWORD_FAIL:
      {
        return Object.assign({}, state, {
          forgotPasswordResponse: false,
          forgotPasswordRequestLoading: false,
          forgotPasswordRequestLoaded: true,
          forgotPasswordRequestFailed: true
        });
      }

    default:
      {
        return state;
      }
  }
}
export const getLoginSuccessResponse = state => state.loginSuccess;
export const getLoginRequestLoading = state => state.loginRequestLoading;
export const getLoginRequestLoaded = state => state.loginRequestLoaded;
export const getLoginRequestFailed = state => state.loginRequestFailed;
export const getForgotPasswordResponse = state => state.forgotPasswordResponse;
export const getForgotPasswordRequestLoading = state => state.forgotPasswordRequestLoading;
export const getForgotPasswordRequestLoaded = state => state.forgotPasswordRequestLoaded;
export const getForgotPasswordRequestFailed = state => state.forgotPasswordRequestFailed;
